+
+func (store *NetworkStore) ConnectAgent(token string, request ConnectAgentRequest) (AgentCredentials, error) {
+	for name, value := range map[string]string{"team_id": request.TeamID, "member_id": request.MemberID, "session_id": request.SessionID, "agent": request.AgentType, "provider": request.Provider} {
+		if err := validateText(name, value, 1, 200); err != nil { return AgentCredentials{}, err }
+	}
+	if err := validateText("model", request.Model, 0, 200); err != nil { return AgentCredentials{}, err }
+	store.mu.Lock()
+	defer store.mu.Unlock()
+	team, ok := store.state.Teams[request.TeamID]; if !ok { return AgentCredentials{}, ErrTeamNotFound }
+	member, ok := team.Members[request.MemberID]
+	if !ok || !tokenMatches(token, member.ConnectorHash) { return AgentCredentials{}, ErrUnauthorized }
+	agentID, err := randomValue("agent_", 12); if err != nil { return AgentCredentials{}, err }
+	agentToken, err := randomValue("agent_token_", 32); if err != nil { return AgentCredentials{}, err }
+	now := store.now().UTC().Format(time.RFC3339Nano)
+	team.Agents[agentID] = &agentRecord{ID: agentID, MemberID: member.ID, SessionID: strings.TrimSpace(request.SessionID), AgentType: strings.TrimSpace(request.AgentType), Provider: strings.TrimSpace(request.Provider), Model: strings.TrimSpace(request.Model), TokenHash: tokenHash(agentToken), LastHeartbeat: now, LastActivity: now}
+	if err := store.persistLocked(); err != nil { delete(team.Agents, agentID); return AgentCredentials{}, err }
+	store.publishLocked(request.TeamID, "agent.connected", agentID, team.Agents[agentID])
+	return AgentCredentials{AgentID: agentID, AgentToken: agentToken}, nil
+}
+
+func (store *NetworkStore) Heartbeat(agentID, token string, request HeartbeatRequest) (ConnectedAgent, error) {
+	if err := validateHeartbeat(request); err != nil { return ConnectedAgent{}, err }
+	store.mu.Lock()
+	defer store.mu.Unlock()
+	team, record := store.findAgentLocked(agentID)
+	if record == nil { return ConnectedAgent{}, ErrAgentNotFound }
+	if !tokenMatches(token, record.TokenHash) { return ConnectedAgent{}, ErrUnauthorized }
+	record.MissionID = strings.TrimSpace(request.MissionID)
+	record.Branch = strings.TrimSpace(request.Branch)
+	record.ChangedFiles = append([]string(nil), request.ChangedFiles...)
+	record.CheckpointID = strings.TrimSpace(request.CheckpointID)
+	record.Blocker = strings.TrimSpace(request.Blocker)
+	if strings.TrimSpace(request.LastActivity) != "" { record.LastActivity = request.LastActivity }
+	record.LastHeartbeat = store.now().UTC().Format(time.RFC3339Nano)
+	if err := store.persistLocked(); err != nil { return ConnectedAgent{}, err }
+	agent := store.publicAgentLocked(team, record)
+	store.publishLocked(team.ID, "agent.heartbeat", agentID, agent)
+	return agent, nil
+}
+
+func (store *NetworkStore) Agents(teamID, token string) ([]ConnectedAgent, error) {
+	store.mu.RLock()
+	defer store.mu.RUnlock()
+	team, ok := store.state.Teams[teamID]
+	if !ok { return nil, ErrTeamNotFound }
+	if !tokenMatches(token, team.AdminHash) { return nil, ErrUnauthorized }
+	agents := make([]ConnectedAgent, 0, len(team.Agents))
+	for _, record := range team.Agents { agents = append(agents, store.publicAgentLocked(team, record)) }
+	sort.Slice(agents, func(i, j int) bool { return agents[i].ID < agents[j].ID })
+	return agents, nil
+}
+
+func (store *NetworkStore) Subscribe(teamID, token string) (<-chan TeamEvent, func(), error) {
+	store.mu.Lock()
+	defer store.mu.Unlock()
+	team, ok := store.state.Teams[teamID]
+	if !ok { return nil, nil, ErrTeamNotFound }
+	if !tokenMatches(token, team.AdminHash) { return nil, nil, ErrUnauthorized }
+	channel := make(chan TeamEvent, 16)
+	if store.subscribers[teamID] == nil { store.subscribers[teamID] = map[chan TeamEvent]bool{} }
+	store.subscribers[teamID][channel] = true
+	cancel := func() {
+		store.mu.Lock(); defer store.mu.Unlock()
+		if store.subscribers[teamID][channel] { delete(store.subscribers[teamID], channel); close(channel) }
+	}
+	return channel, cancel, nil
+}
+
+func (store *NetworkStore) findAgentLocked(agentID string) (*teamRecord, *agentRecord) {
+	for _, team := range store.state.Teams { if agent := team.Agents[agentID]; agent != nil { return team, agent } }
+	return nil, nil
+}
+
+func (store *NetworkStore) publicAgentLocked(team *teamRecord, record *agentRecord) ConnectedAgent {
+	member := team.Members[record.MemberID]
+	lastHeartbeat, _ := time.Parse(time.RFC3339Nano, record.LastHeartbeat)
+	return ConnectedAgent{ID: record.ID, TeamID: team.ID, MemberID: record.MemberID, Name: member.Name, Role: member.Role, SessionID: record.SessionID, AgentType: record.AgentType, Provider: record.Provider, Model: record.Model, Online: store.now().Sub(lastHeartbeat) <= AgentOnlineWindow, MissionID: record.MissionID, Branch: record.Branch, ChangedFiles: append([]string(nil), record.ChangedFiles...), CheckpointID: record.CheckpointID, Blocker: record.Blocker, LastActivity: record.LastActivity, LastHeartbeat: record.LastHeartbeat}
+}
+
+func (store *NetworkStore) publishLocked(teamID, eventType, agentID string, value any) {
+	store.eventID++
+	data, _ := json.Marshal(value)
+	event := TeamEvent{ID: store.eventID, Type: eventType, TeamID: teamID, AgentID: agentID, At: store.now().UTC().Format(time.RFC3339Nano), Data: data}
+	for channel := range store.subscribers[teamID] { select { case channel <- event: default: } }
+}
+
+func (store *NetworkStore) persistLocked() error {
+	content, err := json.MarshalIndent(store.state, "", "  "); if err != nil { return err }
+	content = append(content, '\n')
+	if len(content) > maxNetworkFileBytes { return fmt.Errorf("network state exceeds %d bytes", maxNetworkFileBytes) }
+	directory := filepath.Dir(store.path)
+	if err := os.MkdirAll(directory, 0o700); err != nil { return fmt.Errorf("create network state directory: %w", err) }
+	temporary, err := os.CreateTemp(directory, ".spidey-network-*"); if err != nil { return err }
+	temporaryPath := temporary.Name()
+	defer os.Remove(temporaryPath)
+	if err := temporary.Chmod(0o600); err != nil { temporary.Close(); return err }
+	if _, err := temporary.Write(content); err != nil { temporary.Close(); return err }
+	if err := temporary.Sync(); err != nil { temporary.Close(); return err }
+	if err := temporary.Close(); err != nil { return err }
+	if err := os.Rename(temporaryPath, store.path); err != nil { return fmt.Errorf("replace network state: %w", err) }
+	return nil
+}
+
+func validateHeartbeat(request HeartbeatRequest) error {
+	for name, value := range map[string]string{"mission_id": request.MissionID, "branch": request.Branch, "checkpoint_id": request.CheckpointID, "blocker": request.Blocker, "last_activity": request.LastActivity} {
+		limit := 200; if name == "blocker" { limit = 500 }
+		if err := validateText(name, value, 0, limit); err != nil { return err }
+	}
+	if len(request.ChangedFiles) > maxChangedFiles { return fmt.Errorf("changed_files exceeds %d entries", maxChangedFiles) }
+	for _, path := range request.ChangedFiles {
+		if err := validateText("changed file", path, 1, 500); err != nil { return err }
+		clean := filepath.ToSlash(filepath.Clean(path))
+		if filepath.IsAbs(path) || clean == ".." || strings.HasPrefix(clean, "../") { return errors.New("changed files must be repository-relative") }
+	}
+	if request.LastActivity != "" { if _, err := time.Parse(time.RFC3339Nano, request.LastActivity); err != nil { return errors.New("last_activity must be RFC3339") } }
+	return nil
+}
+
+func validateText(name, value string, minimum, maximum int) error {
+	value = strings.TrimSpace(value)
+	if len(value) < minimum { return fmt.Errorf("%s is required", name) }
+	if len(value) > maximum { return fmt.Errorf("%s exceeds %d bytes", name, maximum) }
+	if strings.ContainsAny(value, "\x00\r\n") { return fmt.Errorf("%s contains control characters", name) }
+	return nil
+}
+
+func randomValue(prefix string, bytes int) (string, error) {
+	buffer := make([]byte, bytes)
+	if _, err := rand.Read(buffer); err != nil { return "", fmt.Errorf("generate credential: %w", err) }
+	return prefix + base64.RawURLEncoding.EncodeToString(buffer), nil
+}
+
+func tokenHash(token string) string { sum := sha256.Sum256([]byte(token)); return hex.EncodeToString(sum[:]) }
+
+func tokenMatches(token, expectedHash string) bool {
+	actual, err := hex.DecodeString(tokenHash(token)); if err != nil { return false }
+	expected, err := hex.DecodeString(expectedHash); if err != nil || len(actual) != len(expected) { return false }
+	return subtle.ConstantTimeCompare(actual, expected) == 1
+}
